#' @title Plot example cell log ratios
#'
#' @description
#' Plots gene-level and chromosome arm-level log ratio
#' profiles for a selected cell.
#'
#' Gene expression values are centred relative to a
#' reference population and displayed across the genome
#' together with chromosome arm-level log ratio values.
#'
#'
#'
#' @param xenium.obj Normalised Xenium object
#' @param cell_id Cell identifier to plot
#' @param arm_ratios Matrix of chromosome arm log ratio
#' values generated by compute_arm_ratios().
#' @param reference_groups Groups used to construct the
#' reference population for gene-level log ratio
#' calculation.
#'
#' @returns A ggplot2 object showing gene-level and
#' chromosome arm-level log-ratio profiles for a
#' selected cell.
#'
#' @examples
#' \dontrun{
#' # Plot example log ratio cell profile
#' plot_cell_log_ratios(xenium.obj = xenium.obj,
#'                     cell_id = "aamfeehk-1",
#'                     arm_ratios = arm_ratios,
#'                     reference_groups = c("Fallopian Tube Epithelium",
#'                     "Secretory Epithelial Cells"))}
#'
#' @export
plot_cell_log_ratios <- function(
    xenium.obj,
    cell_id,
    arm_ratios,
    reference_groups
) {

  # Check cell exists
  if (!cell_id %in% colnames(xenium.obj)) {

    stop(
      paste(
        "Cell not found:",
        cell_id
      )
    )

  }

  # Built-in annotation
  gene_info <- hg38_gene_info %>%
    dplyr::filter(
      hgnc_symbol %in% rownames(xenium.obj)
    )

  chrom_info <- hg38_chrom_info

  # Expression matrix
  log_mat <- xenium.obj@assays$Xenium$data[
    gene_info$hgnc_symbol,
    ,
    drop = FALSE
  ]

  # Reference cells
  reference_cells <- rownames(
    xenium.obj@meta.data[
      xenium.obj@meta.data$group %in% reference_groups,
      ,
      drop = FALSE
    ]
  )

  if (length(reference_cells) == 0) {

    stop(
      "No cells found for the specified reference_groups"
    )

  }

  # Mean reference expression
  log_ref_mean <- Matrix::rowMeans(
    log_mat[
      ,
      reference_cells,
      drop = FALSE
    ]
  )

  # Gene-level log ratios
  vec <- log_mat[, cell_id] -
    log_ref_mean[rownames(log_mat)]

  gene_plot <- cbind(
    gene_info,
    expr = as.vector(vec)
  )

  # Arm-level log ratios
  arm_ratio_plot <- data.frame(
    chrom_arm = rownames(arm_ratios),
    mean_arm_expr = arm_ratios[, cell_id]
  )

  arm_ratio_plot$chrom <- sub(
    "_.*",
    "",
    arm_ratio_plot$chrom_arm
  )

  arm_ratio_plot$arm <- sub(
    ".*_",
    "",
    arm_ratio_plot$chrom_arm
  )

  arm_ratio_plot <- arm_ratio_plot[, c(
    "chrom",
    "arm",
    "mean_arm_expr"
  )]

  arm_ratio_plot <- arm_ratio_plot %>%
    dplyr::left_join(
      chrom_info %>%
        dplyr::select(
          chrom,
          p_start,
          p_end,
          q_start,
          q_end
        ),
      by = "chrom"
    )

  ggplot2::ggplot(gene_plot, ggplot2::aes(x = cum_mid, y = expr)) +
    ggplot2::geom_point(
      alpha = 0.5,
      size = 1
    ) +
    ggplot2::geom_vline(
      xintercept = chrom_info$cum_centromere_mid,
      linetype = "dashed",
      linewidth = 0.3
    ) +
    ggplot2::geom_vline(
      xintercept = chrom_info$cum_length,
      linewidth = 0.3
    ) +
    ggplot2::geom_segment(
      data = subset(
        arm_ratio_plot,
        arm == "p"
      ),
      ggplot2::aes(
        x = p_start,
        xend = p_end,
        y = mean_arm_expr,
        yend = mean_arm_expr,
        colour = arm
      ),
      linewidth = 0.8
    ) +
    ggplot2::geom_segment(
      data = subset(
        arm_ratio_plot,
        arm == "q"
      ),
      ggplot2::aes(
        x = q_start,
        xend = q_end,
        y = mean_arm_expr,
        yend = mean_arm_expr,
        colour = arm
      ),
      linewidth = 0.8
    ) +
    ggplot2::scale_colour_manual(
      values = c(
        p = "#E69F00",
        q = "#0072B2"
      ),
      labels = c(
        p = "Arm p",
        q = "Arm q"
      ),
      name = "Arm"
    ) +
    ggplot2::scale_x_continuous(
      breaks = chrom_info$cum_chromosome_mid,
      labels = chrom_info$chrom,
      expand = c(0, 0)
    ) +
    ggplot2::theme_classic() +
    ggplot2::theme(
      axis.text.x = ggplot2::element_text(
        colour = "black",
        size = 6,
        angle = 60,
        hjust = 1
      ),
      axis.text.y = ggplot2::element_text(
        colour = "black",
        size = 6
      ),
      axis.title.y = ggplot2::element_text(
        colour = "black",
        size = 8
      ),
      legend.position = "none"
    ) +
    ggplot2::labs(
      x = "Chromosome",
      y = "Log ratio"
    ) +
    ggplot2::ylim(-9, 9)

}
